func (c *Int64) Store(_ *rt.Task, value int64)      { c.value.Store(value) }
func (c *Int64) Add(_ *rt.Task, delta int64) int64 { old := c.value.Load(); runtime.Gosched(); c.value.Store(old + delta); return old + delta }

